schema.content:
Table "game" {
  "id" INTEGER [pk, not null]
  "genre_id" INTEGER
  "game_name" TEXT
}

Table "game_platform" {
  "id" INTEGER [pk, not null]
  "game_publisher_id" INTEGER
  "platform_id" INTEGER
  "release_year" INTEGER
}

Table "game_publisher" {
  "id" INTEGER [pk, not null]
  "game_id" INTEGER
  "publisher_id" INTEGER
}

Table "genre" {
  "id" INTEGER [pk, not null]
  "genre_name" TEXT
}

Table "platform" {
  "id" INTEGER [pk, not null]
  "platform_name" TEXT
}

Table "publisher" {
  "id" INTEGER [pk, not null]
  "publisher_name" TEXT
}

Table "region" {
  "id" INTEGER [pk, not null]
  "region_name" TEXT
}

Table "region_sales" {
  "region_id" INTEGER
  "game_platform_id" INTEGER
  "num_sales" REAL
}



Ref: "game"."genre_id" > "genre"."id"

Ref: "game_publisher"."publisher_id" > "publisher"."id"

Ref: "game_publisher"."game_id" > "game"."id"

Ref: "game_platform"."platform_id" > "platform"."id"

Ref: "game_platform"."game_publisher_id" > "game_publisher"."id"

Ref: "region_sales"."region_id" > "region"."id"

Ref: "region_sales"."game_platform_id" > "game_platform"."id"
